hold_ticks := 0
fired := false
if (all(#MotionSensor).motionSensor_motion ==| true) {
if (fired == false) {
hold_ticks = hold_ticks + 1
        if (hold_ticks >= 1) {
tmp = (#Living_Light).light_currentBrightness + 10
            if (tmp > 100) {
tmp = 100
}
(#Living_Light).light_moveToBrightness(tmp, 0)
            if ((#Living_Light).light_currentBrightness >= 100) {
break
}
fired = true
}
}
}
else {
hold_ticks = 0
    fired = false
}

